import type { ReactNode } from 'react'

import { cx } from '~/lib/cx'
import styles from './nav-icon.module.scss'

export interface NavIconProps {
  icon: ReactNode
  label: string
  active?: boolean
  href?: string
  onClick?: () => void
  className?: string
}

/** Compact icon + label navigation target. */
export function NavIcon({ icon, label, active, href, onClick, className }: NavIconProps) {
  const content = (
    <>
      <span className={styles.icon}>{icon}</span>
      <span className={styles.label}>{label}</span>
    </>
  )
  const classes = cx(styles.root, active && styles.active, className)

  return href ? (
    <a className={classes} href={href} aria-current={active ? 'page' : undefined}>
      {content}
    </a>
  ) : (
    <button type="button" className={classes} onClick={onClick} aria-current={active ? 'page' : undefined}>
      {content}
    </button>
  )
}

@use '../../styles' as vz;

.root {
  display: flex;
  align-items: center;
  gap: vz.space(2);
  padding: vz.space(2) vz.space(3);
  border-radius: vz.radius('md');
  color: vz.color('muted-foreground');
  font-size: vz.font-size('sm');

  &:hover {
    background: vz.color('accent');
    color: vz.color('accent-foreground');
  }
}

.active {
  background: vz.color('primary', 0.1);
  color: vz.color('primary');
  font-weight: 600;
}

.icon svg {
  width: 18px;
  height: 18px;
}
